# STAR web prototype: ANOVA for RCBD, running the recovered STAR R engine.
# The engine sources in ./star are generated by scripts/build_app.R from engine/R.
library(shiny)

for (f in sort(list.files("star", pattern = "\\.R$", full.names = TRUE))) source(f, local = FALSE)

run_quiet <- function(expr) {
  err <- NULL
  val <- NULL
  out <- capture.output(val <- tryCatch(expr, error = function(e) { err <<- conditionMessage(e); NULL }))
  list(text = out, value = val, error = err)
}

copy_js <- "
Shiny.addCustomMessageHandler('copy_text', function(msg) {
  var done = function(ok) { Shiny.setInputValue('copy_status', {ok: ok, what: msg.what, t: Date.now()}); };
  var fallback = function() {
    var ta = document.createElement('textarea'); ta.value = msg.text;
    ta.style.position = 'fixed'; ta.style.opacity = '0'; document.body.appendChild(ta); ta.select();
    var ok = false; try { ok = document.execCommand('copy'); } catch (e) {}
    document.body.removeChild(ta); done(ok);
  };
  if (navigator.clipboard && window.isSecureContext) {
    navigator.clipboard.writeText(msg.text).then(function() { done(true); }, fallback);
  } else { fallback(); }
});"

ui <- fluidPage(
  tags$head(tags$script(HTML(copy_js))),
  titlePanel("STAR (prototype): ANOVA for a randomized complete block design"),
  sidebarLayout(
    sidebarPanel(
      radioButtons("src", "Data", c("Example (rice yield, 6 N levels x 3 reps)" = "ex", "Upload CSV" = "up")),
      conditionalPanel("input.src == 'up'", fileInput("file", "CSV file", accept = ".csv")),
      uiOutput("var_pickers"),
      selectInput("pw", "Mean comparison (run when the effect is significant)",
                  c("Automatic: LSD if <= 5 levels, else Tukey" = "", "LSD" = "LSD", "Tukey HSD" = "HSD",
                    "Duncan" = "duncan", "SNK" = "SNK", "Scheffe" = "scheffe")),
      actionButton("go_aov", "Run ANOVA", class = "btn-primary")
    ),
    mainPanel(
      uiOutput("aov_msg"),
      actionButton("cp_aov", "Copy output"), downloadButton("dl_aov", "Download TXT"),
      verbatimTextOutput("aov_out")
    )
  )
)

server <- function(input, output, session) {
  dat <- reactive({
    if (input$src == "ex") return(read.csv("example_rcbd.csv"))
    req(input$file); read.csv(input$file$datapath)
  })
  output$var_pickers <- renderUI({
    nm <- names(dat())
    tagList(
      selectInput("resp", "Response variable", nm, selected = tail(nm, 1)),
      selectInput("trt", "Treatment factor", nm, selected = nm[min(2, length(nm))]),
      selectInput("blk", "Block / replication", nm, selected = nm[1])
    )
  })
  aov_res <- eventReactive(input$go_aov, {
    d <- dat(); req(input$resp, input$trt, input$blk)
    if (length(unique(c(input$resp, input$trt, input$blk))) < 3) return(list(error = "Choose three different columns."))
    if (!is.numeric(d[[input$resp]])) return(list(error = "The response variable must be numeric."))
    assign("star_data", d, envir = globalenv())
    args <- list(data = "star_data", design = "RCBD", respvar = input$resp, factor1 = input$trt, rep1 = input$blk)
    # In STAR, pwVar lists the *response* variables that use pwTest; others get the automatic choice
    if (nzchar(input$pw)) { args$pwTest <- input$pw; args$pwVar <- input$resp }
    res <- run_quiet(do.call(AOVTest, args))
    if (!is.null(res$error)) return(list(error = res$error))
    list(text = res$text)
  })
  output$aov_msg <- renderUI({ r <- aov_res(); if (!is.null(r$error)) div(class = "alert alert-danger", r$error) })
  aov_text <- reactive({ r <- aov_res(); req(is.null(r$error)); paste(r$text, collapse = "\n") })
  output$aov_out <- renderText(aov_text())
  output$dl_aov <- downloadHandler("star_anova_rcbd.txt", function(file) writeLines(aov_text(), file))
  observeEvent(input$cp_aov, session$sendCustomMessage("copy_text", list(what = "ANOVA output", text = aov_text())))
  observeEvent(input$copy_status, {
    st <- input$copy_status
    showNotification(if (isTRUE(st$ok)) paste(st$what, "copied to clipboard") else "Copy failed: select the text and copy manually",
                     type = if (isTRUE(st$ok)) "message" else "error", duration = 3)
  })
}

shinyApp(ui, server)
